"""G2 (SK, 31 Oct 2026, after defect 36): the server refuses a vw tool older than its minimum by name, so a laptop that was not updated is told to update.
Raised to 0.65.0 with the design/126 build: its server reads the new tool's commands."""
from app.config import Settings
from app.main import plugin_refusal


def test_an_older_tool_is_told_to_update_and_the_minimum_passes():   # integration step A raised it to 0.79.0 (SK, 12 Nov 2026: a hand-in says how it was made); design/179 raised it to 0.78.0: the motion skill reads the brief's style
    minimum = Settings.model_fields['PLUGIN_MIN_VERSION'].default
    assert minimum == '0.107.0'   # release 0.125.0 / 0.107.0 (23 Nov 2026), the VW-25 set (the brief's `{library_chapters}`, `vw master others`, a trim in seconds); before: release 0.122.0 / 0.106.0 (22 Nov 2026), design/223: the new take process; before: release 0.121.0 / 0.105.0 (20 Nov 2026): layout B (the layout video flat with thin outlines, a purple back mark; the checker's helper text names them); before: release 0.120.0 / 0.104.0 (20 Nov 2026): releases 1 to 4 (the served text now names `vw motion render --wait`, `vw visuals propose --answers` and `vw defect --shot`, which an older tool lacks; 0.119.0 / 0.103.0 was never deployed): Claude's check with judgement (a line answered "na"), one click, the closed check box, step 7's order (a look with "na" is refused by an older server, and an older tool lacks the helper texts); before: release 0.118.0 / 0.102.0 (20 Nov 2026): step 7 on the page, the step 6 fix set, the page fixes (`vw visuals page --shown`, `loading_write`, `--new-page`); design/221: 0.101.0 (`vw motion parts`, `vw motion upload --still`, the closed page of step 6); design/218: 0.100.0 (`vw font --sample`); design/217 (step 6 on the page, `vw visuals pictures --looks`); design/216b: 0.98.0 (`--things`); design/216: 0.97.0 (the sets screen, `say`, `--fetch`); design/215: 0.96.0 (an older page shows the older words and cannot send the tick of a correction); design/214: 0.95.0 (an older tool's look at a set carries no line answers and would be refused); design/213: 0.94.0; design/212: 0.93.0; design/211: 0.92.0; design/210: 0.91.0; design/209: 0.90.0; design/207: 0.89.0; design/206: 0.88.0; design/205: 0.87.0; design/204: 0.86.0; design/192 and 194 (design/193: 0.84.0; design/188: 0.82.0; design/190: 0.83.0)
    said = plugin_refusal('/api/runs/x/visuals/images', '0.83.0', minimum)
    assert said and '0.83.0' in said and '0.107.0' in said and 'update it' in said
    assert plugin_refusal('/api/runs/x/visuals/images', '0.107.0', minimum) is None and plugin_refusal('/api/runs/x', '0.107.1', minimum) is None and plugin_refusal('/api/runs/x/visuals/images', '0.106.2', minimum)
